import {
  memo, useCallback, useEffect, useMemo, useState,
} from '../../lib/teact/teact';
import { getActions } from '../../global';

import { TME_LINK_PREFIX } from '../../config';
import {
  isUsernameValid, MAX_USERNAME_LENGTH, MIN_UPDATE_USERNAME_LENGTH, USERNAME_REGEX,
} from '../../util/entities/username';
import { debounce } from '../../util/schedulers';

import useLang from '../../hooks/useLang';
import usePreviousDeprecated from '../../hooks/usePreviousDeprecated';

import InputText from '../ui/InputText';

type OwnProps = {
  // Checks the public link of the chat instead of the current user's username
  chatId?: string;
  currentUsername?: string;
  asLink?: boolean;
  isLoading?: boolean;
  isUsernameAvailable?: boolean;
  checkedUsername?: string;
  onChange: (value: string) => void;
};

const LINK_PREFIX_REGEX = /https:\/\/t\.me\/?/i;

const runDebouncedForCheckUsername = debounce((cb) => cb(), 250, false);

const UsernameInput = ({
  chatId,
  currentUsername,
  asLink,
  isLoading,
  isUsernameAvailable,
  checkedUsername,
  onChange,
}: OwnProps) => {
  const { checkUsername, checkPublicLink } = getActions();
  const [username, setUsername] = useState(currentUsername || '');

  const lang = useLang();
  const label = asLink ? lang('SetUrlPlaceholder') : lang('Username');

  const previousIsUsernameAvailable = usePreviousDeprecated(isUsernameAvailable);
  const renderingIsUsernameAvailable = currentUsername !== username
    ? (isUsernameAvailable ?? previousIsUsernameAvailable) : undefined;
  const isChecking = username && currentUsername !== username && checkedUsername !== username;

  const [usernameSuccess, usernameError] = useMemo(() => {
    if (!username.length) {
      return [];
    }

    if (username.length < MIN_UPDATE_USERNAME_LENGTH) {
      return [undefined, lang(asLink ? 'SetUrlShort' : 'UsernameShort')];
    }
    if (username.length > MAX_USERNAME_LENGTH) {
      return [undefined, lang(asLink ? 'SetUrlLong' : 'UsernameLong')];
    }
    if (!USERNAME_REGEX.test(username)) {
      return [undefined, lang(asLink ? 'SetUrlInvalid' : 'UsernameInvalid')];
    }

    if (renderingIsUsernameAvailable === undefined || isChecking) {
      return [];
    }

    // Variable `isUsernameAvailable` is initialized with `undefined`, so a strict false check is required
    return [
      renderingIsUsernameAvailable
        ? (asLink ? lang('SetUrlAvailable', { url: label }) : lang('UsernameAvailable', { username: label }))
        : undefined,
      renderingIsUsernameAvailable === false ? lang(asLink ? 'SetUrlInUse' : 'UsernameInUse') : undefined,
    ];
  }, [username, renderingIsUsernameAvailable, isChecking, lang, asLink, label]);

  useEffect(() => {
    setUsername(currentUsername || '');
  }, [asLink, currentUsername]);

  const handleUsernameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value.trim();
    // Prevent prefix editing
    if (asLink && !value.match(LINK_PREFIX_REGEX)) {
      if (!value.length) {
        setUsername('');
        onChange?.('');
      }
      return;
    }
    const newUsername = value.replace(LINK_PREFIX_REGEX, '');

    setUsername(newUsername);

    const isValid = newUsername === '' ? true : isUsernameValid(newUsername, true);
    if (!isValid) return;

    onChange?.(newUsername);

    runDebouncedForCheckUsername(() => {
      if (newUsername === currentUsername) return;

      if (chatId) {
        checkPublicLink({ chatId, username: newUsername });
      } else {
        checkUsername({ username: newUsername });
      }
    });
  }, [asLink, chatId, checkPublicLink, checkUsername, currentUsername, onChange]);

  return (
    <InputText
      value={`${asLink ? TME_LINK_PREFIX : ''}${username}`}
      onChange={handleUsernameChange}
      label={isChecking ? lang('Checking') : label}
      error={usernameError}
      success={usernameSuccess}
      readOnly={isLoading}
      teactExperimentControlled
    />
  );
};

export default memo(UsernameInput);
